import 'package:cel/cel.dart';

void main() {
  final input = "request.auth.claims.group == 'admin'";
  final e = Environment.standard();
  final ast = e.compile(input);
  final p = e.makeProgram(ast);
  final result = p.evaluate({
    'request': {
      'auth': {
        'claims': {'group': 'admin'}
      }
    }
  });
  print(result); // true
}
